// Run: go test -fuzz=FuzzDDLReferences -fuzztime=20s ./internal/flashback
package flashback

import (
	"testing"

	"binlogviz/internal/mysqlexpr"
)

func FuzzDDLReferences(f *testing.F) {
	for _, sql := range []string{
		// Statement shapes the reader knows (ddlrefs_test.go).
		"RENAME TABLE rn.t2 TO rn.tmp, rn.t1 TO rn.t2, rn.tmp TO rn.t1",
		"RENAME TABLE other.x TO other.y, t2 TO t1",
		"rename tables a.b to c.d;",
		"DROP TABLE `rn`.`z`,`rn`.`t1` /* generated by server */",
		"DROP TEMPORARY TABLE IF EXISTS z, `we``ird` CASCADE",
		"DROP VIEW IF EXISTS v1, s2.v2",
		"TRUNCATE TABLE t1", "TRUNCATE rn.t1",
		"ALTER TABLE rn.t1 RENAME TO rn.t9",
		"ALTER TABLE z ADD COLUMN c INT, RENAME AS other.t1",
		"ALTER TABLE z RENAME COLUMN a TO b, RENAME INDEX i TO j",
		"ALTER TABLE b ADD CONSTRAINT fk FOREIGN KEY (x) REFERENCES a (id) ON DELETE CASCADE",
		"ALTER ONLINE IGNORE TABLE IF EXISTS qa.b ADD INDEX iv (v), ALGORITHM=INPLACE",
		"ALTER TABLE qa.b COMMENT 'RENAME TO qa.a; SELECT'",
		"CREATE TABLE IF NOT EXISTS n (id INT PRIMARY KEY, v VARCHAR(10) DEFAULT 'x')",
		"CREATE TABLE n LIKE rn.t1",
		"CREATE OR REPLACE TEMPORARY TABLE n (LIKE t1)",
		"CREATE UNIQUE INDEX ix USING BTREE ON rn.t1 (v)",
		"DROP INDEX ix ON t1 ALGORITHM=INPLACE LOCK=NONE",
		"DROP DATABASE IF EXISTS shop",
		"CREATE SCHEMA IF NOT EXISTS shop DEFAULT CHARACTER SET utf8mb4",
		"ALTER DATABASE CHARACTER SET utf8mb4",
		"-- note\nDROP TABLE # trailing\n t1",
		"GRANT SELECT ON rn.t1 TO 'u'@'%'",
		"CREATE USER 'u'@'%' IDENTIFIED BY 'x'",
		"DROP USER u", "RENAME USER a TO b", "SET PASSWORD FOR u = 'x'",
		// Refused shapes and malformed near-misses.
		"", "RENAME TABLE a TO", "RENAME TABLE IF EXISTS a TO b",
		"DROP TABLE a, ", "DROP TABLE `t1", "DROP TABLE a /* open",
		"DROP TABLE a; DROP TABLE t1", "DROP TABLE \"t1\"",
		"DROP TABLE a /*!50001 , t1 */", "DROP TABLE a /*M!100100 , t1 */",
		"DROP TABLE z /*!99999 , t1 */",
		"ALTER TABLE z EXCHANGE PARTITION p WITH TABLE t1",
		"ALTER TABLE z RENAME", "ALTER VIEW v AS SELECT * FROM t1",
		"CREATE TABLE n AS SELECT * FROM t1", "CREATE TABLE n TABLE t1",
		"CREATE VIEW v AS SELECT 1", "DROP TRIGGER tr",
		"TRUNCATE TABLE t1 WAIT 1", "SET GLOBAL x = 1", "OPTIMIZE TABLE t1",
		"CREATE TABLE n (c INT CHECK (c LIKE 'a%'))",
		"SELECT 1", "INSERT INTO t VALUES (1)", "DROP",
	} {
		f.Add(sql, "rn", byte(0))
	}
	f.Fuzz(func(t *testing.T, sql, session string, mode byte) {
		d := mysqlexpr.Dialect{
			ANSIQuotes: mode&1 != 0,
			MariaDB:    mode&2 != 0,
			VersionID:  80046,
		}
		if mode&4 != 0 {
			d.VersionID = 0
		}
		_, _ = ddlReferences(sql, session, "", d)
	})
}
